class Pipeline:
    def __init__(self):
        self.steps = []

    def add(self, fn):
        self.steps.append(fn)
        return self

    def run(self, inp):
        result = inp
        for fn in self.steps:
            result = fn(result)
        return result

step1 = lambda x: 'A:' + x
step2 = lambda x: x.upper()

result = Pipeline().add(step1).add(step2).run('hello')
print(result)

