class Template:
    def __init__(self, tmpl):
        self.tmpl = tmpl

    def format(self, **kwargs):
        result = self.tmpl
        for k, v in kwargs.items():
            result = result.replace(f'{{{k}}}', str(v))
        return result

    def invoke(self, data):
        return self.format(**data)

tpl = Template('{subject} 수업: {topic}')
result = tpl.invoke({'subject': 'AI', 'topic': 'LangChain'})
print(result)
```

