class SessionStore:
    def __init__(self):
        self.store = {}

    def get(self, session_id):
        if session_id not in self.store:
            self.store[session_id] = []
        return self.store[session_id]

    def add(self, session_id, role, content):
        self.get(session_id).append({'role': role, 'content': content})

    def count(self, session_id):
        return len(self.get(session_id))

ss = SessionStore()
ss.add('alice', 'user', 'Q1')
ss.add('alice', 'assistant', 'A1')
ss.add('bob', 'user', 'Hi')
print(ss.count('alice'))
print(ss.count('bob'))

class SimpleRetriever:
    def __init__(self):
        self.docs = []

    def add_doc(self, content, keywords):
        self.docs.append({'content': content, 'keywords': keywords})

    def search(self, query, k=2):
        matches = [d['content'] for d in self.docs if query.lower() in d['keywords'].lower()]
        return matches[:k]

sr = SimpleRetriever()
sr.add_doc('Python 기초', 'python programming')
sr.add_doc('LangChain 소개', 'langchain ai')
sr.add_doc('Python 심화', 'python advanced')
print(sr.search('python', k=2))
